head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.createWindow = function() {
    var ws_s = "<input class=\"sp11\" value=\"";
    var ws_m = "subTitle";
    var ws_e = "\"/>";
    var c_cnt = 1;
    var c_subName = "/sample/common_link/windowContainer_spa_SKT-575_(WSQ-1155)_sub";
    var c_xmlName = ".xml";
    for (var i = 1; i <= c_cnt; i++) {
        var windowHeaderHTML = ws_s + ws_m + i + ws_e;
        windowContainer1.createWindow("windowContainer_spa_SKT-575_(WSQ-1155)_sub" + i, null, c_subName + i + c_xmlName, null, null, "existWindow",
            null, null, windowHeaderHTML);
    }
}
scwin.setMenu = function(dataArr) {
    windowContainer1.setMenu(dataArr, dataArr.length * 21);
}
scwin.doInit = function() {
    this.createWindow();
    this.setMenu(["화면 닫기", "듀얼 모니터로 보기", "멀티 뷰로 보기", "공유하기"]);
}
scwin.trigger1_onclick = function() {
    scwin.createWindow();
}
scwin.trigger2_onclick = function() {
    windowContainer1.doCloseAll();
}
scwin.checkVal = function() {
    return scwin.__getDom($p.id + 'windowContainer1_subWindow1').style.display == 'none';
}
scwin.checkVal1 = function() {
    return scwin.__getDom($p.id + 'windowContainer1_subWindow1').style.display == 'block';
}
scwin.checkVal2 = function() {
    return document.getElementsByClassName('sp11')[0].value == 'subTitle1';
}
scwin.onpageload = function() {
    scwin.doInit();
};
